(()=>{
  if(window.__cssFrameworksAdded)return;
  window.__cssFrameworksAdded=true;

  const card=(color,title,text)=>`<article style="max-width:440px;padding:22px;border:1px solid #cbd5e1;border-radius:14px;font-family:system-ui;background:#fff"><h2 style="margin-top:0;color:${color}">${title}</h2><p style="color:#334155">${text}</p><button style="padding:9px 14px;border:0;border-radius:8px;color:#fff;background:${color}">Comenzar</button></article>`;
  const F=(topic,name,description,code,preview,tip)=>T(topic,name,description,code,preview,[],{kind:'Framework CSS',tip});
  const add=(title,description,quote,challenge,items)=>sections.push({title,description,quote,challenge,items});

  add('Frameworks CSS · Introducción','Comprende qué aportan los frameworks CSS, sus formas de instalación y las diferencias entre componentes prediseñados y clases de utilidad.','“Un framework acelera patrones conocidos; CSS sigue explicando por qué funcionan.”','Compara los cuatro enfoques y elige uno para reproducir una tarjeta responsive.',[
    F('Concepto','¿Qué es un framework CSS?','Un framework CSS reúne estilos, convenciones y clases reutilizables para resolver layouts, tipografía, espaciado, colores y diseño responsive. Reduce el tiempo inicial, pero no sustituye la cascada, la especificidad, el modelo de caja, Flexbox ni Grid: esos fundamentos permiten comprender y personalizar el resultado.','HTML semántico\n      +\nclases del framework\n      +\nCSS propio mínimo\n      ↓\ninterfaz consistente y responsive','<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;font-family:system-ui;text-align:center"><div style="padding:14px;background:#dbeafe">Layout</div><div style="padding:14px;background:#dcfce7">Componentes</div><div style="padding:14px;background:#fef3c7">Responsive</div></div>','Aprende CSS básico antes de depender de las clases de un framework.'),
    F('Instalación','CDN frente a npm','Un CDN permite enlazar un archivo desde HTML y probar rápidamente sin compilación. npm guarda la dependencia en package.json y facilita versiones reproducibles, importaciones selectivas y personalización durante el build. Para una práctica aislada usa CDN; para un proyecto mantenible prefiere npm y fija versiones compatibles.','<!-- Prueba rápida con CDN -->\n<link rel="stylesheet" href="URL-DEL-FRAMEWORK.css">\n\n# Proyecto con dependencias\nnpm install nombre-del-framework','<div style="font-family:system-ui;display:flex;gap:12px"><span style="padding:12px;background:#eff6ff">CDN: aprender</span><span style="padding:12px;background:#ecfdf5">npm: proyecto</span></div>','No mezcles varios frameworks completos: pueden competir en la cascada y aumentar la descarga.'),
    F('Enfoques','Componentes frente a utilidades','Bootstrap, Bulma y Foundation proporcionan patrones con clases de componente; Tailwind combina utilidades pequeñas. Las clases de componente aceleran interfaces convencionales con decisiones ya tomadas. Las utilidades permiten componer un diseño propio, aunque el atributo class resulta más extenso.','<!-- Componente preparado -->\n<button class="btn btn-primary">Guardar</button>\n\n<!-- Composición con utilidades -->\n<button class="rounded-lg bg-blue-600 px-4 py-2 text-white">Guardar</button>','<div style="display:flex;gap:16px;font-family:system-ui"><div style="padding:16px;background:#eff6ff"><strong>Componentes</strong><br>Menos decisiones</div><div style="padding:16px;background:#f5f3ff"><strong>Utilidades</strong><br>Mayor composición</div></div>','Elige según el diseño, el conocimiento del equipo y el mantenimiento esperado.'),
    F('Ruta','Orden de aprendizaje','Cada sección sigue la misma ruta para que puedas comparar sin perderte: instalación, clases básicas, sistema responsive, componentes, personalización y práctica integrada. Repite el mismo resultado con CSS propio al final para reconocer qué reglas aporta realmente el framework.','1. Instalar o enlazar\n2. Aplicar clases básicas\n3. Construir un layout responsive\n4. Usar componentes\n5. Personalizar sin conflictos\n6. Completar una práctica','<ol style="font-family:system-ui;line-height:1.8"><li>Instalación</li><li>Fundamentos</li><li>Responsive</li><li>Componentes</li><li>Personalización</li><li>Práctica</li></ol>','Completa una ruta antes de evaluar otro framework.')
  ]);

  add('Frameworks CSS · Bootstrap','Aprende Bootstrap 5.3 desde la instalación hasta su grid, utilidades, componentes, personalización y una página integrada.','“Bootstrap combina un sistema responsive, utilidades y componentes con una convención consistente.”','Construye una página de cursos responsive usando Bootstrap.',[
    F('Instalación','Instalar Bootstrap','Para una prueba rápida puedes enlazar el CSS compilado desde CDN. El bundle JavaScript es opcional para layout y estilos, pero necesario en componentes interactivos como modal, dropdown y offcanvas. En proyectos con build también puedes instalar bootstrap y Popper mediante npm.','<!-- Dentro de <head> -->\n<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet">\n\n<!-- Antes de </body>, si usas componentes interactivos -->\n<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"></script>\n\n# Alternativa npm\nnpm install bootstrap @popperjs/core','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#93c5fd">Bootstrap CSS cargado</pre>','Incluye doctype HTML5 y meta viewport para que el diseño responsive funcione correctamente.'),
    F('Utilidades','Clases básicas','Bootstrap ofrece utilidades con escalas predefinidas. p-4 añade padding, mb-3 margen inferior, text-primary aplica el color principal y shadow-sm una sombra pequeña. Las clases se combinan en el HTML y evitan escribir reglas nuevas para ajustes comunes.','<article class="p-4 mb-3 border rounded shadow-sm">\n  <h2 class="text-primary">Curso Bootstrap</h2>\n  <p class="text-secondary mb-0">Clases de espacio y color.</p>\n</article>',card('#0d6efd','Curso Bootstrap','Clases de espacio, borde, color y sombra.'),'Consulta la escala del framework; p-4 no significa necesariamente cuatro píxeles.'),
    F('Grid','Sistema responsive','El container limita y centra el contenido; row crea una fila y col distribuye columnas. Bootstrap es mobile first: col-12 ocupa todo el ancho y col-md-6 cambia a media fila desde el breakpoint md. g-3 agrega separación entre columnas y filas.','<div class="container">\n  <div class="row g-3">\n    <div class="col-12 col-md-6">Curso HTML</div>\n    <div class="col-12 col-md-6">Curso CSS</div>\n  </div>\n</div>','<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px;font-family:system-ui"><div style="padding:18px;background:#dbeafe">Curso HTML</div><div style="padding:18px;background:#dbeafe">Curso CSS</div></div>','Diseña primero la columna móvil y añade breakpoints solo cuando el contenido lo necesite.'),
    F('Componentes','Tarjetas, botones y alertas','Los componentes reúnen estructura HTML y clases coordinadas. card, card-body y card-title construyen una tarjeta; btn y btn-primary forman un botón. Respeta el marcado documentado porque las reglas CSS dependen de esa relación entre elementos y clases.','<article class="card shadow-sm">\n  <div class="card-body">\n    <h2 class="card-title h4">HTML y CSS</h2>\n    <p class="card-text">Construye tu primera página.</p>\n    <a href="#" class="btn btn-primary">Ver curso</a>\n  </div>\n</article>',card('#0d6efd','HTML y CSS','Construye tu primera página.'),'Usa elementos semánticos y texto accesible; las clases no sustituyen el significado HTML.'),
    F('Personalización','Variables y Sass','Puedes sobrescribir variables CSS como --bs-primary para ajustes locales o compilar el Sass fuente cuando necesites cambiar el sistema completo de colores, espacios y componentes. Coloca tus reglas después de Bootstrap para que la cascada permita ajustes controlados.','<div class="tema-propio">\n  <button class="btn btn-primary">Guardar</button>\n</div>\n\n<style>\n.tema-propio {\n  --bs-primary: #7c3aed;\n  --bs-primary-rgb: 124, 58, 237;\n}\n</style>','<button style="padding:10px 16px;border:0;border-radius:6px;background:#7c3aed;color:white">Guardar</button>','No uses !important como primera opción; revisa orden, especificidad y variables disponibles.'),
    F('Práctica','Proyecto Bootstrap: academia','Integra container, grid responsive, utilidades y cards en una página de cursos. Construye primero el encabezado, después una rejilla mobile first y finalmente la navegación. Comprueba que las tarjetas cambien de una a dos o tres columnas según el ancho disponible.','1. Carga Bootstrap.\n2. Crea header y navbar.\n3. Añade un container principal.\n4. Construye row con cards col-12 col-md-6 col-xl-4.\n5. Aplica utilidades de espacio y color.\n6. Añade un botón accesible por tarjeta.\n7. Prueba móvil, tableta y escritorio.','<main style="max-width:720px;margin:auto;font-family:system-ui"><h1 style="text-align:center;color:#0d6efd">Academia web</h1><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:14px">'+card('#0d6efd','HTML','Estructura semántica.')+card('#0d6efd','CSS','Diseño responsive.')+'</div></main>','Reproduce después una tarjeta con CSS propio para identificar las reglas que Bootstrap resolvió.')
  ]);

  add('Frameworks CSS · Tailwind','Aprende Tailwind CSS 4 mediante instalación con Vite, utilidades, responsive, estados, componentes reutilizables y personalización.','“Tailwind genera CSS a partir de las clases de utilidad encontradas en tus plantillas.”','Construye un panel responsive con utilidades de Tailwind.',[
    F('Instalación','Instalar Tailwind con Vite','La integración oficial con Vite instala tailwindcss y @tailwindcss/vite, añade el plugin al archivo de configuración e importa Tailwind desde el CSS principal. El proceso analiza las plantillas y genera solamente las utilidades utilizadas. El Play CDN sirve para aprender, no para producción.','npm install tailwindcss @tailwindcss/vite\n\n// vite.config.js\nimport tailwindcss from "@tailwindcss/vite";\nexport default { plugins: [tailwindcss()] };\n\n/* src/style.css */\n@import "tailwindcss";\n\nnpm run dev','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#67e8f9">Tailwind + Vite listo</pre>','Mantén las clases completas en las plantillas para que el analizador pueda detectarlas.'),
    F('Utilidades','Clases básicas','Cada utilidad suele controlar una propiedad concreta: p-6 define padding, rounded-xl el radio, bg-white el fondo, text-slate-600 el texto y shadow-lg la sombra. Las escalas del sistema mantienen consistencia sin crear una clase personalizada para cada bloque.','<article class="rounded-xl border border-slate-200 bg-white p-6 shadow-lg">\n  <h2 class="text-2xl font-bold text-blue-700">Curso Tailwind</h2>\n  <p class="mt-2 text-slate-600">Tarjeta con utilidades.</p>\n</article>',card('#2563eb','Curso Tailwind','Tarjeta construida con utilidades.'),'Agrupa mentalmente las clases por layout, espacio, tipografía, color y estado.'),
    F('Responsive','Variantes por breakpoint','Tailwind aplica primero el estilo móvil y utiliza prefijos como md: o lg: para cambios desde un breakpoint. grid-cols-1 crea una columna; md:grid-cols-2 y xl:grid-cols-3 amplían la distribución sin escribir media queries manuales.','<section class="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">\n  <article class="rounded-lg bg-blue-50 p-4">HTML</article>\n  <article class="rounded-lg bg-blue-50 p-4">CSS</article>\n  <article class="rounded-lg bg-blue-50 p-4">JavaScript</article>\n</section>','<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;font-family:system-ui"><div style="padding:16px;background:#eff6ff">HTML</div><div style="padding:16px;background:#eff6ff">CSS</div><div style="padding:16px;background:#eff6ff">JavaScript</div></div>','No uses un breakpoint por dispositivo específico; úsalo cuando el contenido necesite cambiar.'),
    F('Estados','Hover, focus y dark mode','Las variantes modifican una utilidad bajo una condición. hover:bg-blue-700 responde al puntero y focus-visible:ring añade una señal clara para navegación con teclado. dark: permite cambiar estilos cuando el modo oscuro está activo.','<button class="rounded-lg bg-blue-600 px-4 py-2 text-white\n  hover:bg-blue-700\n  focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-400\n  dark:bg-blue-500 dark:hover:bg-blue-400">\n  Guardar\n</button>','<button style="padding:10px 16px;border:0;border-radius:8px;background:#2563eb;color:white">Guardar</button>','Nunca elimines el outline sin proporcionar un indicador de foco visible equivalente.'),
    F('Personalización','Tema y componentes reutilizables','Tailwind permite definir tokens del tema y reutilizar patrones desde componentes del lenguaje de plantillas. Si un bloque se repite, crea un componente React, Vue o del servidor antes de esconder una gran combinación bajo una clase CSS. Conserva utilidades para variaciones locales.','/* src/style.css */\n@import "tailwindcss";\n\n@theme {\n  --color-marca-600: #7c3aed;\n}\n\n<button class="bg-marca-600 px-4 py-2 text-white">\n  Guardar\n</button>','<button style="padding:10px 16px;border:0;border-radius:8px;background:#7c3aed;color:white">Guardar</button>','Extrae componentes por reutilización o responsabilidad, no únicamente porque class sea largo.'),
    F('Práctica','Proyecto Tailwind: panel','Integra utilidades de layout, espacio, tipografía, responsive y estados en un panel de cursos. Diseña primero para móvil, amplía la cuadrícula por breakpoints y termina revisando foco, contraste y modo oscuro.','1. Configura Tailwind con Vite.\n2. Crea header y navegación flex.\n3. Diseña cards con utilidades.\n4. Construye grid mobile first.\n5. Añade variantes md y xl.\n6. Implementa hover y focus-visible.\n7. Revisa contraste y repetición.','<main style="font-family:system-ui"><h1 style="color:#2563eb">Panel de cursos</h1><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:14px">'+card('#2563eb','HTML','4 lecciones pendientes.')+card('#2563eb','CSS','2 lecciones pendientes.')+'</div></main>','Inspecciona el CSS generado y confirma que las clases usadas estén incluidas.')
  ]);

  add('Frameworks CSS · Bulma','Aprende Bulma desde su único archivo CSS hasta helpers, columnas, componentes, responsive y personalización con Sass.','“Bulma ofrece componentes y helpers CSS sin imponer una biblioteca JavaScript.”','Construye una página de perfil responsive utilizando Bulma.',[
    F('Instalación','Instalar Bulma','Bulma puede cargarse con un link CDN o instalarse como paquete npm. La versión CSS compilada permite comenzar sin herramientas; el paquete incluye Sass para personalizar el tema. Bulma no incorpora JavaScript, así que tú decides cómo controlar menús, modales y otros comportamientos.','<!-- Opción CDN -->\n<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bulma@1.0.4/css/bulma.min.css">\n\n# Opción npm\nnpm install bulma\n\n/* CSS principal */\n@import "bulma/css/bulma.css";','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#c4b5fd">Bulma CSS cargado</pre>','Empieza con el CSS compilado y pasa a Sass solo cuando necesites un tema propio.'),
    F('Elementos','Clases básicas y helpers','Bulma usa clases legibles como title, subtitle, button e is-primary. Helpers como has-text-centered, mt-4 o is-flex resuelven alineación, espacio y visualización. Los modificadores con is- o has- describen variantes y estados.','<section class="section has-text-centered">\n  <h1 class="title has-text-link">Academia web</h1>\n  <p class="subtitle">Aprende construyendo.</p>\n  <button class="button is-link is-rounded">Comenzar</button>\n</section>',card('#485fc7','Academia web','Clases de elementos, color y alineación.'),'Consulta qué elemento base necesita cada modificador; is-link no tiene el mismo efecto aislado.'),
    F('Columnas','Layout responsive','columns agrupa una fila y column define cada columna. Por defecto, las columnas se apilan en móvil y se distribuyen horizontalmente en pantallas mayores. Modificadores como is-half-tablet permiten controlar el ancho desde un breakpoint concreto.','<div class="columns is-multiline">\n  <div class="column is-full-mobile is-half-tablet">HTML</div>\n  <div class="column is-full-mobile is-half-tablet">CSS</div>\n</div>','<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px;font-family:system-ui"><div style="padding:18px;background:#ede9fe">HTML</div><div style="padding:18px;background:#ede9fe">CSS</div></div>','Usa is-multiline cuando las columnas deban pasar a una nueva fila.'),
    F('Componentes','Box, card y media object','box crea un contenedor elevado sencillo; card divide contenido en header, image, content y footer; media organiza imagen y texto. La estructura HTML requerida comunica qué parte recibe cada estilo, mientras los helpers ajustan detalles.','<article class="box">\n  <div class="media">\n    <div class="media-content">\n      <h2 class="title is-4">Curso Bulma</h2>\n      <p class="subtitle is-6">Interfaz basada en CSS.</p>\n      <button class="button is-link">Ver curso</button>\n    </div>\n  </div>\n</article>',card('#485fc7','Curso Bulma','Interfaz basada únicamente en CSS.'),'Añade JavaScript propio únicamente para el comportamiento que el componente necesite.'),
    F('Personalización','Variables CSS y Sass','Bulma expone variables CSS para ajustes locales y variables Sass para construir una versión personalizada. Aplica variables en un contenedor cuando el cambio corresponda a una sección; usa Sass cuando el sistema completo necesite otros tokens de marca.','<section class="tema-propio">\n  <button class="button is-link">Guardar</button>\n</section>\n\n<style>\n.tema-propio {\n  --bulma-link-h: 265deg;\n  --bulma-link-s: 70%;\n}\n</style>','<button style="padding:10px 16px;border:0;border-radius:6px;background:#7c3aed;color:white">Guardar</button>','Verifica en DevTools el nombre y alcance de la variable antes de sobrescribirla.'),
    F('Práctica','Proyecto Bulma: perfil','Combina section, container, columns, box, media, botones y helpers para crear una página de perfil. Añade el comportamiento del menú con JavaScript propio si lo necesitas y conserva aria-expanded sincronizado con su estado visual.','1. Carga Bulma.\n2. Crea navbar y section.\n3. Centra el contenido con container.\n4. Diseña perfil con columns y box.\n5. Añade media para avatar y texto.\n6. Aplica helpers responsive.\n7. Implementa y prueba el menú móvil.','<main style="max-width:680px;margin:auto;font-family:system-ui">'+card('#485fc7','Ana · Desarrolladora web','HTML, CSS y JavaScript.')+'</main>','Prueba el perfil con textos largos, sin imagen y en una pantalla estrecha.')
  ]);

  add('Frameworks CSS · Foundation','Aprende Foundation 6 desde la instalación hasta XY Grid, utilidades, componentes, Sass y una página responsive integrada.','“Foundation prioriza una base flexible para interfaces responsive personalizadas.”','Construye una landing responsive utilizando Foundation.',[
    F('Instalación','Instalar Foundation','Foundation for Sites está disponible por CDN y npm. El CSS compilado permite practicar layout y componentes visuales. Los plugins interactivos requieren el JavaScript de Foundation y sus dependencias; el paquete npm también incluye los archivos Sass para compilación y personalización avanzada.','<!-- CSS compilado -->\n<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/foundation-sites@6.9.0/dist/css/foundation.min.css">\n\n# Alternativa npm\nnpm install foundation-sites','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#7dd3fc">Foundation CSS cargado</pre>','Carga JavaScript solamente si utilizas componentes interactivos que lo requieren.'),
    F('Fundamentos','Contenedores y utilidades','grid-container centra el contenido y establece un ancho máximo; callout resalta información; button estiliza enlaces o botones. Clases de alineación, visibilidad y tipografía permiten ajustes comunes sin crear reglas adicionales.','<main class="grid-container">\n  <div class="callout primary">\n    <h1>Academia web</h1>\n    <p>Aprende con proyectos.</p>\n    <a class="button" href="#cursos">Ver cursos</a>\n  </div>\n</main>',card('#1779ba','Academia web','Aprende con proyectos.'),'Conserva etiquetas semánticas aunque el framework permita estilizar cualquier elemento.'),
    F('XY Grid','Sistema responsive','grid-x crea una fila horizontal, cell define cada celda y grid-margin-x agrega separación. small-12 ocupa todas las columnas en móvil; medium-6 ocupa la mitad desde medium. La combinación expresa el layout responsive directamente en el HTML.','<div class="grid-container">\n  <div class="grid-x grid-margin-x">\n    <article class="cell small-12 medium-6">HTML</article>\n    <article class="cell small-12 medium-6">CSS</article>\n  </div>\n</div>','<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px;font-family:system-ui"><div style="padding:18px;background:#e0f2fe">HTML</div><div style="padding:18px;background:#e0f2fe">CSS</div></div>','Empieza con small y añade medium o large cuando el contenido deje de caber cómodamente.'),
    F('Componentes','Callout, card y reveal','Foundation incluye componentes visuales y plugins interactivos. callout muestra mensajes destacados y card agrupa contenido. Reveal, dropdown y otros componentes requieren inicialización JavaScript; consulta la dependencia concreta antes de incluir todo el bundle.','<article class="card">\n  <div class="card-section">\n    <h2>Curso Foundation</h2>\n    <p>Diseño adaptable con XY Grid.</p>\n    <a href="#" class="button">Comenzar</a>\n  </div>\n</article>',card('#1779ba','Curso Foundation','Diseño adaptable con XY Grid.'),'No incluyas plugins interactivos que la página no utiliza.'),
    F('Personalización','Settings y Sass','El paquete Sass permite modificar tokens antes de compilar. El archivo de settings centraliza paleta, breakpoints, tipografía y opciones de componentes; después se importa Foundation para generar un CSS consistente con esas decisiones.','// _settings.scss\n$primary-color: #7c3aed;\n$global-radius: 8px;\n\n// app.scss\n@import "settings";\n@import "foundation";\n@include foundation-everything;','<button style="padding:10px 16px;border:0;border-radius:8px;background:#7c3aed;color:white">Comenzar</button>','Cambia primero los settings disponibles y reserva las sobrescrituras para casos específicos.'),
    F('Práctica','Proyecto Foundation: landing','Integra grid-container, XY Grid, callout, cards, botones y breakpoints en una landing. Empieza por el contenido semántico, construye la versión móvil y después añade columnas medium y large. Termina revisando qué plugin JavaScript es realmente necesario.','1. Carga Foundation.\n2. Crea header y callout principal.\n3. Añade grid-container.\n4. Construye cursos con grid-x y cell.\n5. Configura small, medium y large.\n6. Personaliza color y radio.\n7. Prueba responsive y accesibilidad.','<main style="max-width:720px;margin:auto;font-family:system-ui"><h1 style="color:#1779ba">Aprende desarrollo web</h1><div style="display:grid;grid-template-columns:repeat(2,1fr);gap:14px">'+card('#1779ba','Frontend','HTML, CSS y JavaScript.')+card('#1779ba','Responsive','Diseño para cada pantalla.')+'</div></main>','Comprueba teclado, contraste, zoom y distribución en móvil antes de terminar.')
  ]);

  const intro=sections.find(section=>section.title==='Frameworks CSS · Introducción');
  intro.items.push(
    F('Decisión','Cuándo usar un framework','Un framework resulta útil cuando el equipo necesita entregar patrones conocidos con rapidez, mantener consistencia entre muchas pantallas o compartir un sistema responsive. CSS propio puede ser mejor para una página pequeña, un diseño muy singular o un proyecto donde el peso y el control fino son prioritarios.','Usa framework si:\n✓ hay muchos patrones repetidos\n✓ el equipo comparte convenciones\n✓ el tiempo inicial es limitado\n\nUsa CSS propio si:\n✓ el diseño es pequeño o muy específico','<div style="font-family:system-ui"><strong>Decisión:</strong> compara alcance, diseño, equipo, peso y mantenimiento.</div>','Realiza una prueba pequeña y mide el CSS final antes de decidir.'),
    F('Accesibilidad','Framework no significa accesible','Las clases pueden aportar contraste, tamaños o focos iniciales, pero la accesibilidad depende también del HTML y del comportamiento. Usa etiquetas semánticas, nombre accesible, navegación con teclado, foco visible, mensajes asociados y estados ARIA sincronizados en componentes interactivos.','<button type="button" aria-expanded="false" aria-controls="menu">\n  Abrir menú\n</button>\n<nav id="menu" hidden>...</nav>','<button style="padding:10px 16px;border:2px solid #2563eb;border-radius:8px">Abrir menú</button>','Prueba teclado, zoom, contraste y lector de pantalla en el resultado real.'),
    F('Diseño','Sistema de diseño y tokens','Un framework es más útil cuando se conecta con decisiones compartidas: colores, tipografía, espacios, radios, sombras y breakpoints. Variables CSS, Sass o la configuración del framework convierten esas decisiones en tokens reutilizables y reducen sobrescrituras inconsistentes.',' :root {\n  --color-marca: #2563eb;\n  --espacio-3: .75rem;\n  --radio: .75rem;\n}\n\n/* Conecta estos tokens con las opciones del framework. */','<article style="font-family:system-ui;padding:16px;border-radius:12px;background:#dbeafe;color:#1e3a8a">Componente basado en tokens</article>','Define pocos tokens con significado antes de crear decenas de variaciones.'),
    F('Producción','Rendimiento y mantenimiento','En producción importa cuánto CSS se descarga, cuánto queda sin utilizar y cuántas reglas propias compiten con el framework. Importa módulos selectivos cuando sea posible, comprime recursos, fija versiones, revisa cambios de actualización y documenta las personalizaciones que alteran el comportamiento predeterminado.','1. Generar build de producción\n2. Medir CSS transferido y no utilizado\n3. Eliminar componentes no usados\n4. Probar regresiones visuales\n5. Registrar versión y personalizaciones','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#a7f3d0">CSS optimizado ✓\nResponsive ✓\nAccesibilidad ✓</pre>','No actualices una versión mayor sin revisar su guía de migración y las pantallas críticas.')
  );

  const beforePractice=(level,items)=>{
    const section=sections.find(entry=>entry.title===`Frameworks CSS · ${level}`);
    section.items.splice(section.items.length-1,0,...items);
  };

  beforePractice('Bootstrap',[
    F('Navegación','Navbar responsive','navbar organiza marca, enlaces y acciones. navbar-expand-lg conserva el menú colapsado hasta el breakpoint grande; el botón toggler necesita atributos data-bs y el bundle JavaScript para abrir o cerrar la navegación. aria-controls, aria-expanded y aria-label describen el comportamiento.','<nav class="navbar navbar-expand-lg bg-body-tertiary">\n  <div class="container">\n    <a class="navbar-brand" href="#">Academia</a>\n    <button class="navbar-toggler" data-bs-toggle="collapse" data-bs-target="#menu" aria-controls="menu" aria-expanded="false" aria-label="Abrir navegación">☰</button>\n    <div id="menu" class="collapse navbar-collapse">\n      <a class="nav-link" href="#cursos">Cursos</a>\n    </div>\n  </div>\n</nav>','<nav style="font-family:system-ui;padding:14px;background:#f1f5f9"><strong>Academia</strong>　Cursos　Contacto</nav>','Prueba que el foco permanezca visible y que aria-expanded cambie con el menú.'),
    F('Formularios','Campos y validación','form-label, form-control y form-select presentan controles consistentes; input-group combina texto o botones visualmente. Los estados is-valid e is-invalid deben acompañar una validación real y mensajes vinculados, no depender solamente de rojo y verde.','<label class="form-label" for="correo">Correo</label>\n<input id="correo" class="form-control is-invalid" type="email" aria-describedby="error" required>\n<div id="error" class="invalid-feedback">Escribe un correo válido.</div>','<form style="font-family:system-ui"><label>Correo</label><br><input style="border:1px solid #dc3545"><p style="color:#b02a37">Escribe un correo válido.</p></form>','Mantén type, required, label y descripción del error aunque uses clases de validación.'),
    F('Datos','Tablas responsive','table aplica estilos base y sus modificadores añaden filas alternas, hover o bordes. table-responsive crea desplazamiento horizontal cuando el contenido no cabe, evitando comprimir columnas hasta volverlas ilegibles. Mantén caption, encabezados th y scope para conservar significado.','<div class="table-responsive">\n<table class="table table-striped table-hover">\n  <caption>Progreso por curso</caption>\n  <thead><tr><th scope="col">Curso</th><th scope="col">Avance</th></tr></thead>\n  <tbody><tr><th scope="row">HTML</th><td>80%</td></tr></tbody>\n</table>\n</div>','<table style="width:100%;border-collapse:collapse;font-family:system-ui"><caption>Progreso por curso</caption><tr><th>Curso</th><th>Avance</th></tr><tr><td>HTML</td><td>80%</td></tr></table>','No reemplaces una tabla de datos por div únicamente para facilitar el estilo.'),
    F('Interacción','Modal y offcanvas','Modal presenta una tarea enfocada sobre la página y offcanvas muestra un panel lateral. Ambos necesitan el bundle JavaScript, estructura documentada y un disparador. Bootstrap gestiona parte del foco y teclado, pero el contenido todavía necesita título, acciones claras y una forma predecible de cerrar.','<button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#detalle">Ver detalle</button>\n<div id="detalle" class="modal" tabindex="-1" aria-labelledby="titulo-modal">\n  <div class="modal-dialog"><div class="modal-content">\n    <div class="modal-header"><h2 id="titulo-modal" class="modal-title">Curso HTML</h2></div>\n  </div></div>\n</div>','<section style="font-family:system-ui;padding:20px;border:1px solid #cbd5e1;border-radius:10px"><h2>Curso HTML</h2><button>Cerrar</button></section>','Usa modal para tareas breves; una página suele ser mejor para contenido largo o enlazable.'),
    F('Utilidades avanzadas','Flex, posición y visibilidad','d-flex activa Flexbox; gap, justify-content y align-items controlan distribución. position-relative, position-absolute y z-index ayudan con capas, mientras visually-hidden oculta texto visualmente y lo conserva para tecnologías de asistencia. Combina utilidades con moderación para no esconder una estructura confusa.','<div class="d-flex flex-column flex-md-row align-items-md-center justify-content-between gap-3">\n  <h2 class="mb-0">Mis cursos</h2>\n  <button class="btn btn-outline-primary">Filtrar</button>\n  <span class="visually-hidden">3 cursos encontrados</span>\n</div>','<div style="display:flex;justify-content:space-between;align-items:center;font-family:system-ui"><h2>Mis cursos</h2><button>Filtrar</button></div>','Prefiere una regla CSS propia si una combinación extensa se repite en muchos archivos.'),
    F('Producción','Importación selectiva y mantenimiento','Con npm y Sass puedes importar únicamente partes necesarias, personalizar variables antes de compilar y cargar plugins JavaScript individuales. Esto reduce recursos y evita incluir interacciones no utilizadas. Después del build revisa tamaño, compatibilidad, mapa de fuentes y regresiones de componentes personalizados.','// styles.scss\n$primary: #7c3aed;\n@import "bootstrap/scss/functions";\n@import "bootstrap/scss/variables";\n@import "bootstrap/scss/bootstrap-grid";\n@import "bootstrap/scss/buttons";\n\n// JavaScript necesario\nimport Modal from "bootstrap/js/dist/modal";','<pre style="padding:16px;background:#0f172a;color:#a7f3d0">Grid + botones + modal\nSin componentes innecesarios</pre>','Mide antes y después; una importación parcial solo compensa si el proceso sigue siendo mantenible.')
  ]);

  beforePractice('Tailwind',[
    F('Layout','Flexbox y Grid','Las utilidades flex y grid activan los modelos nativos de CSS. items-center, justify-between, gap-4, grid-cols-* y col-span-* expresan la composición. El comportamiento sigue siendo CSS: comprender ejes, tamaño intrínseco y desbordamiento permite corregir layouts sin probar clases al azar.','<header class="flex items-center justify-between gap-4">\n  <h1 class="text-2xl font-bold">Academia</h1>\n  <nav class="flex gap-3">...</nav>\n</header>\n<section class="grid grid-cols-12 gap-4">\n  <aside class="col-span-12 lg:col-span-3">Filtros</aside>\n  <main class="col-span-12 lg:col-span-9">Cursos</main>\n</section>','<div style="display:grid;grid-template-columns:1fr 3fr;gap:14px;font-family:system-ui"><aside style="padding:14px;background:#e0f2fe">Filtros</aside><main style="padding:14px;background:#f8fafc">Cursos</main></div>','Aprende primero Flexbox y Grid; las utilidades son nombres breves para esas propiedades.'),
    F('Tipografía','Texto, tamaño y ritmo','font-*, text-*, leading-* y tracking-* controlan familia, peso, tamaño, altura de línea y espaciado entre letras. max-w-prose limita párrafos y space-y-* aporta ritmo vertical. Una escala pequeña y consistente mejora legibilidad más que muchos tamaños aislados.','<article class="max-w-prose space-y-4">\n  <h1 class="text-3xl font-bold tracking-tight text-slate-900">Guía de CSS</h1>\n  <p class="text-base leading-7 text-slate-600">Aprende mediante ejemplos progresivos.</p>\n</article>','<article style="max-width:60ch;font-family:system-ui"><h1>Guía de CSS</h1><p style="line-height:1.7;color:#475569">Aprende mediante ejemplos progresivos.</p></article>','No reduzcas texto principal por debajo de un tamaño legible para hacer caber el diseño.'),
    F('Formularios','Diseñar controles accesibles','Las utilidades estilizan label, input, select y estados de foco sin cambiar su comportamiento nativo. Usa focus-visible, disabled y aria-invalid para reflejar estados. Tailwind no aporta validación: HTML y JavaScript siguen siendo responsables de restricciones y mensajes.','<label class="block text-sm font-medium" for="correo">Correo</label>\n<input id="correo" type="email" required aria-invalid="true" class="mt-1 w-full rounded-lg border border-red-500 px-3 py-2 focus-visible:ring-2 focus-visible:ring-blue-500">\n<p class="mt-1 text-sm text-red-700">Correo no válido.</p>','<form style="font-family:system-ui"><label>Correo</label><br><input style="padding:8px;border:1px solid #dc2626;border-radius:8px"><p style="color:#b91c1c">Correo no válido.</p></form>','Comprueba contraste, foco y mensajes; no comuniques el error solo con color.'),
    F('Selectores','Grupos, atributos y elementos hijos','Variantes como group-hover, peer-checked, aria-expanded y data-* permiten responder a estados presentes en el HTML. Los modificadores de elementos hijos aplican utilidades a contenido generado. Estas capacidades reducen JavaScript visual, pero deben mantener atributos semánticos sincronizados.','<button class="group flex items-center gap-2" aria-expanded="false">\n  Menú\n  <span class="transition group-aria-expanded:rotate-180">⌄</span>\n</button>\n<label class="flex gap-2"><input class="peer" type="checkbox"><span class="peer-checked:line-through">Tarea</span></label>','<div style="font-family:system-ui"><button>Menú ⌄</button><p><input type="checkbox"> Tarea</p></div>','La clase responde al atributo, pero tu lógica debe actualizar ese atributo correctamente.'),
    F('Efectos','Transiciones y animación','transition, duration y ease controlan cambios entre estados; transform, opacity y translate expresan el efecto. motion-reduce permite disminuir o quitar movimiento cuando el usuario lo solicita. Anima propiedades económicas y evita convertir una transición decorativa en requisito para entender la interfaz.','<button class="rounded-lg bg-blue-600 px-4 py-2 text-white transition hover:-translate-y-0.5 hover:bg-blue-700 motion-reduce:transform-none motion-reduce:transition-none">\n  Guardar\n</button>','<button style="padding:10px 16px;background:#2563eb;color:white;border:0;border-radius:8px">Guardar</button>','Prueba la preferencia reduce motion y conserva respuesta inmediata a la acción.'),
    F('Producción','Detección de clases y build','Tailwind examina archivos fuente como texto y genera las utilidades detectadas. Construir nombres mediante fragmentos dinámicos puede impedir que existan en el CSS final; usa nombres completos o mapea variantes a cadenas estáticas. Ejecuta el build, revisa la salida y prueba rutas poco frecuentes.','const colores = {\n  info: "bg-blue-600 text-white",\n  error: "bg-red-600 text-white"\n};\n\n// Evitar: `bg-${color}-600`\n// Build\nnpm run build','<pre style="padding:16px;background:#0f172a;color:#a7f3d0">Clases completas detectadas ✓</pre>','Mantén rutas de contenido correctas y no agregues safelist masivas sin medir su costo.')
  ]);

  beforePractice('Bulma',[
    F('Navegación','Navbar y menú móvil','navbar organiza marca, enlaces y menús. Bulma proporciona el CSS, pero no cambia is-active automáticamente; un script debe alternarlo tanto en navbar-burger como en navbar-menu y actualizar aria-expanded. Sin JavaScript, los enlaces deben seguir siendo accesibles en una presentación alternativa.','<button class="navbar-burger" aria-label="Abrir menú" aria-expanded="false" data-target="menu">\n  <span></span><span></span><span></span><span></span>\n</button>\n<div id="menu" class="navbar-menu">\n  <a class="navbar-item" href="#cursos">Cursos</a>\n</div>','<nav style="font-family:system-ui;padding:14px;background:#f5f5f5"><strong>Academia</strong>　Cursos　Contacto</nav>','Sincroniza clase y aria-expanded en el mismo manejador de clic.'),
    F('Formularios','Field, control e input','field agrupa una entrada con su label, controles, ayuda y errores; control envuelve input, select o iconos. Los modificadores is-success e is-danger aportan estilo, pero la validación y asociación del mensaje siguen dependiendo de HTML y JavaScript.','<div class="field">\n  <label class="label" for="correo-bulma">Correo</label>\n  <div class="control"><input id="correo-bulma" class="input is-danger" type="email" aria-describedby="error-bulma"></div>\n  <p id="error-bulma" class="help is-danger">Correo no válido.</p>\n</div>','<form style="font-family:system-ui"><label>Correo</label><br><input style="padding:8px;border:1px solid #f14668"><p style="color:#cc0f35">Correo no válido.</p></form>','Usa field para estructura visual y conserva atributos nativos de validación.'),
    F('Datos','Table y contenido desplazable','table aplica estilos a una tabla semántica; is-striped, is-hoverable e is-fullwidth agregan variaciones. table-container permite desplazamiento horizontal en contenido ancho. Mantén caption, th y scope porque Bulma no añade significado accesible por sí mismo.','<div class="table-container">\n<table class="table is-striped is-hoverable is-fullwidth">\n  <caption>Avance de cursos</caption>\n  <thead><tr><th scope="col">Curso</th><th scope="col">Avance</th></tr></thead>\n  <tbody><tr><th scope="row">CSS</th><td>70%</td></tr></tbody>\n</table>\n</div>','<table style="width:100%;font-family:system-ui"><caption>Avance de cursos</caption><tr><th>Curso</th><th>Avance</th></tr><tr><td>CSS</td><td>70%</td></tr></table>','Usa tablas para relaciones tabulares, no para maquetar columnas.'),
    F('Interacción','Modal, tabs y estados','Bulma define la presentación de modal, tabs y dropdown, pero el proyecto controla apertura, cierre, foco y teclado. is-active muestra el estado visual. Para un modal, mueve el foco al contenido, permite cerrar con Escape y devuelve el foco al disparador.','<button class="button is-link" aria-haspopup="dialog">Abrir detalle</button>\n<div class="modal is-active" role="dialog" aria-modal="true" aria-labelledby="titulo-bulma">\n  <div class="modal-background"></div>\n  <div class="modal-content box"><h2 id="titulo-bulma" class="title">Detalle</h2></div>\n</div>','<section style="font-family:system-ui;padding:20px;border:1px solid #dbdbdb"><h2>Detalle</h2><button>Cerrar</button></section>','La clase abre visualmente el modal; implementa también su comportamiento accesible.'),
    F('Responsive','Helpers de visibilidad y espaciado','Helpers como is-hidden-mobile o is-flex-tablet cambian presentación por breakpoint, mientras las escalas m-*, p-* y gap-* controlan espacio. Ocultar contenido visualmente también lo retira del flujo; no escondas información necesaria para completar una tarea.','<div class="is-flex-tablet is-justify-content-space-between p-4">\n  <h2 class="title is-4 mb-0">Cursos</h2>\n  <p class="is-hidden-mobile">Vista ampliada</p>\n</div>','<div style="display:flex;justify-content:space-between;font-family:system-ui;padding:16px"><h2>Cursos</h2><p>Vista ampliada</p></div>','Decide el breakpoint observando el contenido, no copiando un dispositivo específico.'),
    F('Producción','Importación modular y Sass','El paquete Sass permite importar módulos y configurar variables para generar un tema. Una importación selectiva reduce el CSS si la aplicación solo usa ciertas piezas, pero exige mantener dependencias entre módulos. Documenta variables cambiadas y verifica todas las variantes de los componentes.','@use "bulma/sass" with (\n  $link: #7c3aed,\n  $family-primary: "Inter", sans-serif\n);\n\n// O importar únicamente módulos requeridos según la guía modular.','<pre style="padding:16px;background:#0f172a;color:#c4b5fd">Tema Bulma compilado ✓</pre>','Mantén la importación completa hasta que una medición justifique la configuración modular.')
  ]);

  beforePractice('Foundation',[
    F('Navegación','Top Bar y menús','Top Bar distribuye marca, enlaces y acciones; los plugins responsive navigation pueden cambiar la presentación según el ancho. Cuando un botón controla el menú, proporciona nombre, relación con el panel y estado expandido. Incluye únicamente el JavaScript requerido por el patrón elegido.','<div class="top-bar">\n  <div class="top-bar-left"><strong>Academia</strong></div>\n  <div class="top-bar-right">\n    <ul class="menu"><li><a href="#cursos">Cursos</a></li><li><a href="#contacto">Contacto</a></li></ul>\n  </div>\n</div>','<nav style="display:flex;justify-content:space-between;padding:14px;background:#e6f6fb;font-family:system-ui"><strong>Academia</strong><span>Cursos　Contacto</span></nav>','Prueba navegación por teclado y menú estrecho antes de añadir más niveles.'),
    F('Formularios','Grid de formularios y estados','Los controles adoptan estilos base y XY Grid permite alinear campos. Las clases de error presentan el estado visual, pero label, restricciones HTML y mensajes asociados siguen siendo necesarios. Agrupa campos por significado, no únicamente para aprovechar columnas.','<form>\n  <div class="grid-x grid-margin-x">\n    <label class="cell medium-6">Nombre <input type="text" required></label>\n    <label class="cell medium-6">Correo <input type="email" required></label>\n  </div>\n  <button class="button" type="submit">Guardar</button>\n</form>','<form style="font-family:system-ui"><label>Nombre <input></label> <label>Correo <input type="email"></label> <button>Guardar</button></form>','En móvil permite que los campos ocupen el ancho disponible y conserven etiquetas visibles.'),
    F('Datos','Tablas y desplazamiento','Las clases de Foundation mejoran presentación de tablas, mientras un contenedor responsive puede manejar desbordamiento. Conserva los elementos table, caption, thead, tbody y th para describir relaciones. Si hay demasiadas columnas, considera reducir datos secundarios además de permitir scroll.','<div class="table-scroll">\n<table>\n  <caption>Progreso por curso</caption>\n  <thead><tr><th scope="col">Curso</th><th scope="col">Avance</th></tr></thead>\n  <tbody><tr><th scope="row">JavaScript</th><td>65%</td></tr></tbody>\n</table>\n</div>','<table style="width:100%;font-family:system-ui"><caption>Progreso por curso</caption><tr><th>Curso</th><th>Avance</th></tr><tr><td>JavaScript</td><td>65%</td></tr></table>','Comprueba encabezados y lectura lineal, no solamente el aspecto de las filas.'),
    F('Interacción','Reveal y Off-canvas','Reveal presenta un diálogo y Off-canvas un panel lateral. Ambos requieren Foundation JavaScript, inicialización y marcado específico. Configura títulos, acciones y cierre; comprueba foco, Escape y retorno al disparador. El panel no debe ser la única forma de acceder a contenido esencial.','<button class="button" data-open="detalle">Ver detalle</button>\n<div class="reveal" id="detalle" data-reveal aria-labelledby="titulo-foundation">\n  <h2 id="titulo-foundation">Curso CSS</h2>\n  <button class="close-button" data-close aria-label="Cerrar">×</button>\n</div>','<section style="font-family:system-ui;padding:20px;border:1px solid #1779ba"><h2>Curso CSS</h2><button>Cerrar</button></section>','Inicializa Foundation una sola vez después de cargar sus dependencias.'),
    F('Responsive','Visibility y orden','Las clases show-for-* y hide-for-* controlan visibilidad por breakpoint; flex-order-* puede cambiar el orden visual. El orden del DOM debe seguir siendo lógico para teclado y lectura, aunque el diseño lo reorganice. Oculta solamente contenido redundante o no esencial.','<aside class="cell medium-4 medium-order-1">Filtros</aside>\n<main class="cell medium-8 medium-order-2">Resultados</main>\n<p class="show-for-medium">Usa los filtros laterales.</p>','<div style="display:grid;grid-template-columns:1fr 2fr;gap:12px;font-family:system-ui"><aside>Filtros</aside><main>Resultados</main></div>','Verifica que el orden de tabulación coincida con una lectura comprensible.'),
    F('Producción','Componentes selectivos y Sass','foundation-everything genera el conjunto completo, mientras mixins individuales permiten incluir solo grid, botones o componentes elegidos. Los plugins JavaScript también pueden cargarse de forma selectiva respetando sus dependencias. Mide la diferencia antes de asumir la complejidad de un build parcial.','@import "foundation";\n@include foundation-global-styles;\n@include foundation-xy-grid-classes;\n@include foundation-button;\n@include foundation-card;\n\n// Añadir otros mixins únicamente cuando se usen.','<pre style="padding:16px;background:#0f172a;color:#7dd3fc">Grid + botón + card\nBuild selectivo</pre>','Mantén un listado de mixins requeridos junto a los componentes usados por la aplicación.')
  ]);

  beforePractice('Bootstrap',[
    F('Carpetas','Estructura de un proyecto Bootstrap','En una página pequeña basta enlazar el CSS desde index.html. Con npm y Sass, separa el archivo que configura Bootstrap del CSS específico de componentes y páginas. JavaScript contiene la inicialización de plugins; public almacena recursos sin procesar y dist es salida generada, por lo que no debe editarse manualmente.','mi-bootstrap/\n├─ public/\n├─ src/\n│  ├─ scss/\n│  │  ├─ _variables.scss # cambios antes de importar Bootstrap\n│  │  ├─ components/     # estilos propios de tarjetas, navbar...\n│  │  ├─ pages/\n│  │  └─ main.scss       # punto de entrada CSS\n│  ├─ js/\n│  │  └─ main.js         # imports e inicialización de plugins\n│  └─ index.html\n├─ package.json\n├─ vite.config.js\n└─ dist/                 # salida del build','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#93c5fd">src/\n  scss/components/\n  scss/pages/\n  scss/main.scss\n  js/main.js</pre>','No modifiques bootstrap.css ni archivos dentro de node_modules; personaliza mediante variables y estilos propios.')
  ]);
  beforePractice('Tailwind',[
    F('Carpetas','Estructura de un proyecto Tailwind','Tailwind puede vivir en un proyecto Vite sin una jerarquía especial. Mantén el CSS de entrada en styles, componentes o plantillas en src y recursos estáticos en public. Si se usa con React, Vue o Svelte, conserva la estructura de ese framework; Tailwind solo añade el plugin y el @import del CSS principal.','mi-tailwind/\n├─ public/\n├─ src/\n│  ├─ components/       # componentes HTML o del framework\n│  ├─ pages/\n│  ├─ styles/\n│  │  └─ main.css       # @import "tailwindcss" y tema\n│  └─ main.js\n├─ index.html\n├─ package.json\n└─ vite.config.js       # plugin @tailwindcss/vite','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#67e8f9">src/\n  components/\n  pages/\n  styles/main.css\nvite.config.js</pre>','No crees un archivo CSS por cada conjunto de utilidades; extrae un componente cuando el patrón se repita.')
  ]);
  beforePractice('Bulma',[
    F('Carpetas','Estructura de un proyecto Bulma','Con CDN solo necesitas HTML y tus estilos posteriores. Con npm y Sass, crea un punto de entrada que configure e importe Bulma, parciales para componentes propios y una carpeta JavaScript para comportamientos que Bulma no incluye. dist representa el resultado compilado y assets guarda recursos fuente o públicos según el build.','mi-bulma/\n├─ public/\n├─ src/\n│  ├─ sass/\n│  │  ├─ _theme.scss      # variables y configuración\n│  │  ├─ components/      # extensiones propias\n│  │  └─ main.scss        # importa Bulma y parciales\n│  ├─ js/\n│  │  ├─ navbar.js        # apertura del menú\n│  │  └─ modal.js\n│  └─ index.html\n├─ package.json\n├─ vite.config.js\n└─ dist/','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#c4b5fd">src/\n  sass/components/\n  sass/main.scss\n  js/navbar.js\n  js/modal.js</pre>','Mantén el comportamiento accesible cerca del componente que controla, aunque Bulma solo proporcione CSS.')
  ]);
  beforePractice('Foundation',[
    F('Carpetas','Estructura de un proyecto Foundation','Un proyecto Foundation con Sass separa settings, punto de entrada, componentes propios y JavaScript. _settings.scss configura el framework antes de compilar; app.scss incluye los mixins necesarios; js inicializa Foundation y plugins elegidos. No edites dist ni el paquete instalado porque se regeneran al construir o actualizar.','mi-foundation/\n├─ public/\n├─ src/\n│  ├─ scss/\n│  │  ├─ _settings.scss   # tokens y opciones de Foundation\n│  │  ├─ components/\n│  │  └─ app.scss         # mixins del framework\n│  ├─ js/\n│  │  └─ app.js           # inicialización y plugins\n│  └─ index.html\n├─ package.json\n├─ vite.config.js\n└─ dist/                  # salida compilada','<pre style="padding:16px;border-radius:10px;background:#0f172a;color:#7dd3fc">src/\n  scss/_settings.scss\n  scss/components/\n  scss/app.scss\n  js/app.js</pre>','Incluye únicamente los mixins y plugins que aparecen en las páginas reales.')
  ]);

  buildNav();
  render();
})();
